public static class Base64Url
{
    public static string Encode(byte[] input)
    {
        // Chuyển sang Base64 thường, sau đó thay thế ký tự theo chuẩn RFC 4648
        string base64 = Convert.ToBase64String(input);
        return base64.Replace("+", "-").Replace("/", "_").TrimEnd('=');
    }

    public static byte[] Decode(string input)
    {
        string base64 = input.Replace("-", "+").Replace("_", "/");
        // Bù lại padding '=' nếu thiếu
        switch (base64.Length % 4)
        {
            case 2: base64 += "=="; break;
            case 3: base64 += "="; break;
        }
        return Convert.FromBase64String(base64);
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

public static class ManualJwtGenerator
{
    public static string CreateToken(object payloadData, string secretKey)
    {
        var header = new { alg = "HS256", typ = "JWT" };

        // 1. Serialize và Base64Url Header
        byte[] headerBytes = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(header));
        string headerEncoded = Base64Url.Encode(headerBytes);

        // 2. Serialize và Base64Url Payload
        byte[] payloadBytes = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(payloadData));
        string payloadEncoded = Base64Url.Encode(payloadBytes);

        // 3. Ghép phần Header và Payload
        string messageToSign = $"{headerEncoded}.{payloadEncoded}";
        byte[] messageBytes = Encoding.UTF8.GetBytes(messageToSign);

        // 4. Ký HMAC-SHA256 bằng Secret Key
        byte[] keyBytes = Encoding.UTF8.GetBytes(secretKey);
        using var hmac = new HMACSHA256(keyBytes);
        byte[] signatureBytes = hmac.ComputeHash(messageBytes);
        string signatureEncoded = Base64Url.Encode(signatureBytes);

        return $"{messageToSign}.{signatureEncoded}";
    }
}

public static bool ValidateToken(string token, string secretKey, out JsonDocument? payloadDoc)
{
    payloadDoc = null;
    var parts = token.Split('.');
    if (parts.Length != 3) return false;

    string messageToSign = $"{parts[0]}.{parts[1]}";
    byte[] expectedSigBytes;
    using (var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secretKey)))
    {
        expectedSigBytes = hmac.ComputeHash(Encoding.UTF8.GetBytes(messageToSign));
    }

    byte[] actualSigBytes = Base64Url.Decode(parts[2]);

    //  Bắt buộc so sánh an toàn bằng FixedTimeEquals
    if (!CryptographicOperations.FixedTimeEquals(expectedSigBytes, actualSigBytes))
    {
        return false; // Chữ ký bị giả mạo!
    }

    // Kiểm tra thời hạn hết hạn (exp claim)
    byte[] payloadBytes = Base64Url.Decode(parts[1]);
    payloadDoc = JsonDocument.Parse(payloadBytes);
    if (payloadDoc.RootElement.TryGetProperty("exp", out var expElem))
    {
        long exp = expElem.GetInt64();
        long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        if (now > exp) return false; // Token đã hết hạn!
    }

    return true;
}

