public class RsaJwtEngine
{
    // 1. Ký bằng Private Key tại Identity Server
    public static string SignRS256(string messageToSign, RSA privateKeyRsa)
    {
        byte[] dataBytes = Encoding.UTF8.GetBytes(messageToSign);
        byte[] signature = privateKeyRsa.SignData(
            dataBytes, 
            HashAlgorithmName.SHA256, 
            RSASignaturePadding.Pkcs1);

        return Base64Url.Encode(signature);
    }

    // 2. Xác thực bằng Public Key tại Microservices con
    public static bool VerifyRS256(string messageToSign, string signatureEncoded, RSA publicKeyRsa)
    {
        byte[] dataBytes = Encoding.UTF8.GetBytes(messageToSign);
        byte[] signatureBytes = Base64Url.Decode(signatureEncoded);

        return publicKeyRsa.VerifyData(
            dataBytes, 
            signatureBytes, 
            HashAlgorithmName.SHA256, 
            RSASignaturePadding.Pkcs1);
    }
}

