public class JwtBlacklistMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IDistributedCache _cache;

    public JwtBlacklistMiddleware(RequestDelegate next, IDistributedCache cache)
    {
        _next = next;
        _cache = cache;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.User.Identity?.IsAuthenticated == true)
        {
            var jti = context.User.FindFirst(JwtRegisteredClaimNames.Jti)?.Value;
            if (!string.IsNullOrEmpty(jti))
            {
                var isBlacklisted = await _cache.GetStringAsync($"jwt:blacklist:{jti}");
                if (!string.IsNullOrEmpty(isBlacklisted))
                {
                    context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                    await context.Response.WriteAsync("Token này đã bị thu hồi hoặc đăng xuất!");
                    return;
                }
            }
        }
        await _next(context);
    }
}

