public async Task<bool> ProcessPaymentAsync(OrderDto order)
{
    var startTime = DateTime.UtcNow;
    var timer = Stopwatch.StartNew();

    try
    {
        // 1. Ghi nhận Event kinh doanh
        var properties = new Dictionary<string, string>
        {
            { "OrderId", order.Id },
            { "PaymentMethod", order.PaymentMethod },
            { "CustomerTier", order.CustomerTier }
        };
        var metrics = new Dictionary<string, double>
        {
            { "TotalAmount", (double)order.Amount },
            { "ItemCount", order.Items.Count }
        };
        _telemetry.TrackEvent("OrderCheckoutStarted", properties, metrics);

        // Thực hiện thanh toán...
        bool success = await _paymentGateway.ChargeAsync(order);

        timer.Stop();

        // 2. Tự ghi nhận Dependency tùy chỉnh
        _telemetry.TrackDependency(
            dependencyTypeName: "PaymentGateway",
            dependencyName: "StripeChargeApi",
            data: $"Charge for order {order.Id}",
            startTime: startTime,
            duration: timer.Elapsed,
            success: success);

        // 3. Ghi nhận Metric hiệu năng
        _telemetry.GetMetric("PaymentProcessingDurationMs").TrackValue(timer.ElapsedMilliseconds);

        return success;
    }
    catch (Exception ex)
    {
        // 4. Ghi nhận Exception kèm thuộc tính điều tra
        _telemetry.TrackException(ex, new Dictionary<string, string>
        {
            { "FailedOrderId", order.Id },
            { "Amount", order.Amount.ToString() }
        });
        throw;
    }
}

