public class HealthCheckFilterTelemetryProcessor : ITelemetryProcessor
{
    private readonly ITelemetryProcessor _next;

    public HealthCheckFilterTelemetryProcessor(ITelemetryProcessor next)
    {
        _next = next;
    }

    public void Process(ITelemetry item)
    {
        // 1. Nếu là HTTP Request gọi tới endpoint /healthz hoặc /metrics -> DROP NGAY
        if (item is RequestTelemetry request)
        {
            if (request.Url.AbsolutePath.StartsWith("/health", StringComparison.OrdinalIgnoreCase) ||
                request.Url.AbsolutePath.StartsWith("/metrics", StringComparison.OrdinalIgnoreCase))
            {
                return; // Không gọi _next.Process(item) -> Telemetry bị hủy bỏ!
            }
        }

        // 2. Nếu là Dependency SQL có chứa thẻ tín dụng -> Mask lại
        if (item is DependencyTelemetry dependency && dependency.Type == "SQL")
        {
            if (dependency.Data.Contains("card_number", StringComparison.OrdinalIgnoreCase))
            {
                dependency.Data = "[REDACTED_SENSITIVE_SQL_QUERY]";
            }
        }

        // Chuyển tiếp cho processor kế tiếp trong chuỗi
        _next.Process(item);
    }
}

